def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v not in (0, 9))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]
    minr = min(r for r, c in pts)
    minc = min(c for r, c in pts)
    shape = [(r-minr, c-minc) for r, c in pts]
    sh, sw = max(r for r,c in shape)+1, max(c for r,c in shape)+1

    # Find locations where the same shape is represented by background zeros,
    # and mark the full shape in the object's color.
    for dr in range(h-sh+1):
        for dc in range(w-sw+1):
            if all(grid[dr+r][dc+c] == 0 for r,c in shape):
                for r,c in shape:
                    out[dr+r][dc+c] = color
    return out
